// دفاعي — مايرميش أبداً (نمط W2). يطبّع type ويحسب priority + reassurance_flow.
const TYPES = ['access','certificate','payment','payment_intl','site_access','refund','angry','for_ahmed'];
const PRIORITY_BY_TYPE = { angry:'urgent', refund:'high', payment:'high', access:'high', site_access:'high', payment_intl:'normal', certificate:'normal', for_ahmed:'normal' };
const j = $json;
let type = String(j.type || '').toLowerCase().trim().replace(/-/g,'_');
let flag = '';
if (!TYPES.includes(type)) { flag = '⚠️ نوع غير معروف: ' + (j.type || '(فاضي)') + ' — '; type = 'for_ahmed'; }
let priority = String(j.priority || '').toLowerCase().trim();
if (!['normal','high','urgent'].includes(priority)) priority = PRIORITY_BY_TYPE[type] || 'normal';
if (type === 'angry') priority = 'urgent';
const phone = String(j.phone || '').replace(/\D/g,'');
let summary = String(j.summary || '').trim();
if (!summary) summary = '(عمر مبعتش ملخص — راجع المحادثة)';
summary = flag + summary;
return { json: {
  type, priority, phone, summary,
  customerName: String(j.customerName || '').trim(),
  customerEmail: String(j.customerEmail || '').trim(),
  orderId: String(j.orderId || '').trim(),
  screenshotUrl: String(j.screenshotUrl || '').trim(),
  reassuranceFlow: type === 'for_ahmed' ? 'ahmed' : 'support'
} };

const n = $('Normalize & Resolve').first().json;
const ins = $json;
const TYPE_LABEL = {
  access:       'دفع وملقاش الكورس (تفعيل)',
  certificate:  'الشهادة (مش ظاهرة/تحميل/اسم)',
  payment:      'فشل دفع داخلي / تحويل يدوي',
  payment_intl: 'دفع من برّه مصر (كارت أجنبي)',
  site_access:  'الموقع/الحصص مش بتفتح',
  refund:       'طلب استرجاع',
  angry:        'عميل غاضب',
  for_ahmed:    'تواصل خاص لأحمد',
};
const PRIORITY_LABEL = { urgent: 'عاجل', high: 'مهم', normal: 'عادي' };
const PRIORITY_EMOJI = { urgent: '🔴', high: '🟠', normal: '🟢' };
const ROLE_LABEL = { customer: 'العميل', omar: 'عمر', system: 'النظام' };
const snap = Array.isArray(ins.context_snapshot) ? ins.context_snapshot : [];
const chat = snap.map(m => (ROLE_LABEL[m.role] || m.role) + ': ' + m.body).join('
') || '(مفيش رسائل متسجلة)';
const pe = PRIORITY_EMOJI[n.priority] || '🟢';
const subject = `[عمر] ${pe} تصعيد ${TYPE_LABEL[n.type]} — ${n.customerName || 'عميل'} (${n.phone})`;
const body = `🔔 تصعيد جديد من عمر (خدمة عملاء اتعلم ببساطة)

🏷️ النوع: ${TYPE_LABEL[n.type]}
${pe} الأولوية: ${PRIORITY_LABEL[n.priority]}

👤 العميل: ${n.customerName || '—'}
📱 واتساب: ${n.phone}
📧 إيميل: ${n.customerEmail || '—'}
🧾 رقم الأوردر: ${n.orderId || '—'}

📝 ملخص عمر:
${n.summary}

📎 سكرين شوت: ${n.screenshotUrl || 'مفيش'}

💬 آخر رسائل المحادثة:
${chat}

—————
🆔 escalation #${ins.id} · الحالة: مفتوح
الحل بشري: ادخل ظبّط الموضوع، وبعد ما تخلص علّم التصعيد كـ resolved.`;
const esc = String(body).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); return { json: { subject, body: esc.slice(0, 3900), escalationId: ins.id } };

// Telegram-only: يفحص نجاح رنّة التليجرام. الضمان الحقيقي = الـ DB row (Insert Escalation).
const ok = name => { try { const j = $(name).first().json; return !(j && j.error); } catch (e) { return false; } };
const telegram = ok('Telegram Alert');
const ins = $('Insert Escalation').first().json;
const n = $('Normalize & Resolve').first().json;
return { json: {
  ok: true,
  escalation_id: ins.id,
  priority: n.priority,
  type: n.type,
  alerted: { telegram },
  reassurance_flow: n.reassuranceFlow,
  anyOk: telegram
} };

// آخر نود = اللي بيرجع لأداة escalate (الموديل بيستخدم reassurance_flow بس)
const f = $('Finalize').first().json;
return { json: { ok: f.ok, escalation_id: f.escalation_id, priority: f.priority, type: f.type, alerted: f.alerted, reassurance_flow: f.reassurance_flow } };

// تصعيد مكرر خلال 90 ثانية (وكيل + حارس، أو retry) — مفيش رنّة تانية. بنرجّع ack سليم للأداة.
const n = $('Normalize & Resolve').first().json;
const ins = $('Insert Escalation').first().json;
return { json: { ok: true, escalation_id: ins.id, priority: n.priority, type: n.type, alerted: { telegram: false }, reassurance_flow: n.reassuranceFlow, deduped: true } };

